def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    fg = next(v for row in grid for v in row if v != bg)
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == fg]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    out = [row[:] for row in grid]
    for c in range(c0, c1 + 1):
        if out[r0][c] == bg: out[r0][c] = 2
        if out[r1][c] == bg: out[r1][c] = 2
    for r in range(r0, r1 + 1):
        if out[r][c0] == bg: out[r][c0] = 2
        if out[r][c1] == bg: out[r][c1] = 2
    return out

